        disable_search_indexing: { name: 'Pesquisa definida como Manual', description: 'Define o serviço de Pesquisa do Windows como início manual.' },
        disable_memory_compression: { name: 'Compressão de memória desativada', description: 'Desativa a compressão de memória. OK com 32+ GB de RAM.' },
        disable_copilot: { name: 'Copilot desativado', description: 'Desativa o Windows Copilot e seu ícone na barra de tarefas.' },
