        disable_wpbt: { name: 'WPBT (injeção automática UEFI) desativada', description: 'Bloqueia o WPBT — um mecanismo UEFI que permite que fabricantes de hardware injetem software silenciosamente a cada inicialização. Recomendado em hardware OEM.' },
