        disable_mpo: { name: 'MPO desativado (corrige cintilação)', description: 'Situacional: desativa o Multiplane Overlay (MPO). Usar apenas se você experimentar cintilações, flashes pretos ou artefatos na tela — também pode desativar VRR/FreeSync.' },
